/**
 * 全站同步逻辑集中管理（批量提交版）
 *
 * 作用：将所有模块（products / advantages / testimonials / features / heroSlides /
 * about / news / categories / footer / seo / privacy）同步到 GitHub，
 * 所有文件收集完成后通过 createOrUpdateFilesBatch 一次性提交，
 * 只产生一个 commit，只触发一次 GitHub Pages 部署。
 *
 * 两阶段：
 *   1. 收集阶段：遍历所有模块，处理图片（base64→路径替换），收集所有待上传文件
 *   2. 批量提交阶段：一次性把所有文件提交到 GitHub，然后执行 Storage 优化
 *
 * 用法：
 *   const { syncAll } = useSiteWideSync();
 *   await syncAll({
 *     onProgress: (progress) => {},
 *     onModuleDone: (label, success, errorMsg) => {},
 *   });
 */

import { useCallback } from 'react';
import { logger } from '@lark-apaas/client-toolkit-lite';
import { useSyncService, type SyncModuleKey } from '@/context/SyncServiceContext';
import { createOrUpdateFilesBatch, type GithubConfig } from '@/lib/github-api';
import { useProducts } from '@/hooks/useProducts';
import { useAdvantages } from '@/hooks/useAdvantages';
import { useTestimonials } from '@/hooks/useTestimonials';
import { useFeatures } from '@/hooks/useFeatures';
import { useHeroSlides } from '@/hooks/useHeroSlides';
import { useAboutContent } from '@/hooks/useAboutContent';
import { useNews } from '@/hooks/useNews';
import { useCategories } from '@/hooks/useCategories';
import { useFooterSettings } from '@/hooks/useFooterSettings';
import { useSeoSettings } from '@/hooks/useSeoSettings';
import { usePrivacyPolicy } from '@/hooks/usePrivacyPolicy';
import {
  INQUIRY_NOTIFICATION_WORKFLOW_PATH,
  INQUIRY_NOTIFICATION_WORKFLOW_CONTENT,
} from '@/lib/workflow-files';
import {
  generateImageFilename,
  isLocalBase64Image,
  extractBase64FromDataUrl,
} from '@/hooks/useGithubSync';

export interface SyncModuleDefinition {
  key: SyncModuleKey;
  label: string;
  /** 收集阶段：返回处理后的数据（图片字段已替换为 GitHub 路径）和待上传文件列表 */
  collectFn: () => Promise<{ data: unknown; files: PendingFile[] }>;
  /** 提交成功后的 Storage 优化（用 GitHub 路径替换本地 base64） */
  onSuccess?: () => Promise<void> | void;
}

export interface PendingFile {
  path: string;      // 仓库内路径，如 data/products.json
  content: string;   // 内容，文本或 base64
  isBase64: boolean; // 是否为 base64 编码（图片）
}

export interface SiteSyncProgress {
  currentIndex: number;
  total: number;
  currentLabel: string;
  successCount: number;
  errorCount: number;
  errors: { module: string; label: string; message: string }[];
  isSyncing: boolean;
  /** 当前阶段：collecting 收集文件 / committing 批量提交 / optimizing Storage 优化 */
  phase?: 'collecting' | 'committing' | 'optimizing' | 'done';
}

export interface SyncAllOptions {
  onProgress?: (progress: SiteSyncProgress) => void;
  onModuleDone?: (label: string, success: boolean, errorMsg?: string) => void;
  onComplete?: (result: {
    successCount: number;
    errorCount: number;
    errors: { module: string; label: string; message: string }[];
  }) => void;
}

/**
 * 深拷贝数据（JSON 序列化，适合普通对象）
 */
function deepClone<T>(obj: T): T {
  return JSON.parse(JSON.stringify(obj));
}

/**
 * 从 base64 图片数组中提取纯 base64（去掉 data:... 前缀），用于去重
 */
function extractPureBase64(dataUrl: string): string {
  const idx = dataUrl.indexOf(',');
  return idx >= 0 ? dataUrl.slice(idx + 1) : dataUrl;
}

/**
 * 在数据中递归查找 base64 图片，生成待上传文件，并替换数据中的路径
 * 返回处理后的数据和待上传文件列表
 *
 * 注意：不实际上传，只收集。上传在批量提交阶段统一完成。
 */
function collectImagesInData<T>(
  data: T,
  moduleDir: string,
  imageFields: (keyof T)[],
  uploadedCache: Map<string, string>
): { data: T; files: PendingFile[] } {
  const files: PendingFile[] = [];

  const uploadOne = (dataUrl: string): string => {
    const pure = extractPureBase64(dataUrl);
    const cached = uploadedCache.get(pure);
    if (cached) {
      return cached;
    }
    const targetPath = generateImageFilename('image.jpg', moduleDir);
    const { base64 } = extractBase64FromDataUrl(dataUrl);
    files.push({ path: targetPath, content: base64, isBase64: true });
    uploadedCache.set(pure, targetPath);
    return targetPath;
  };

  const processImageField = (obj: Record<string, unknown>, field: string) => {
    const val = obj[field];
    if (typeof val === 'string' && isLocalBase64Image(val)) {
      const targetPath = uploadOne(val);
      obj[field] = `/${targetPath}`;
    }
  };

  const processGalleryField = (obj: Record<string, unknown>, field: string) => {
    const val = obj[field];
    if (field === 'gallery' && Array.isArray(val)) {
      const newGallery: string[] = [];
      for (const img of val) {
        if (typeof img === 'string' && isLocalBase64Image(img)) {
          const targetPath = uploadOne(img);
          newGallery.push(`/${targetPath}`);
        } else if (typeof img === 'string') {
          newGallery.push(img);
        }
      }
      obj[field] = newGallery;
    }
  };

  if (!Array.isArray(data)) {
    const obj = { ...(data as Record<string, unknown>) } as Record<string, unknown>;
    for (const field of imageFields as string[]) {
      processImageField(obj, field);
      processGalleryField(obj, field);
    }
    // image 与 gallery[0] 去重
    const imgVal = obj['image'];
    const galVal = obj['gallery'];
    if (
      typeof imgVal === 'string' &&
      imgVal.startsWith('/') &&
      Array.isArray(galVal) &&
      galVal[0] &&
      typeof galVal[0] === 'string' &&
      galVal[0].startsWith('/') &&
      imgVal !== galVal[0] &&
      isLocalBase64Image((data as Record<string, unknown>)['image'] as string) &&
      isLocalBase64Image(((data as Record<string, unknown>)['gallery'] as string[])[0] || '')
    ) {
      const origImg = (data as Record<string, unknown>)['image'] as string;
      const origGal0 = ((data as Record<string, unknown>)['gallery'] as string[])[0] || '';
      if (extractPureBase64(origImg) === extractPureBase64(origGal0)) {
        obj['image'] = galVal[0];
      }
    }
    return { data: obj as T, files };
  }

  const result: unknown[] = [];
  for (const item of data as unknown[]) {
    if (!item || typeof item !== 'object') {
      result.push(item);
      continue;
    }
    const obj = { ...(item as Record<string, unknown>) } as Record<string, unknown>;
    for (const field of imageFields as string[]) {
      processImageField(obj, field);
      processGalleryField(obj, field);
    }
    // image 与 gallery[0] 去重
    const imgVal = obj['image'];
    const galVal = obj['gallery'];
    const origItem = item as Record<string, unknown>;
    const origImg = typeof origItem['image'] === 'string' ? origItem['image'] : '';
    const origGalArr = Array.isArray(origItem['gallery']) ? (origItem['gallery'] as string[]) : [];
    const origGal0 = origGalArr[0] || '';
    if (
      typeof imgVal === 'string' &&
      imgVal.startsWith('/') &&
      Array.isArray(galVal) &&
      galVal[0] &&
      typeof galVal[0] === 'string' &&
      galVal[0].startsWith('/') &&
      isLocalBase64Image(origImg) &&
      isLocalBase64Image(origGal0) &&
      extractPureBase64(origImg) === extractPureBase64(origGal0)
    ) {
      obj['image'] = galVal[0];
    }
    result.push(obj);
  }

  return { data: result as unknown as T, files };
}

/**
 * 处理单个 base64 图片字段：生成待上传文件，返回 GitHub 路径
 */
function collectSingleImage(
  dataUrl: string,
  filename: string,
  moduleDir: string,
  files: PendingFile[],
  uploadedCache: Map<string, string>
): string {
  const pure = extractPureBase64(dataUrl);
  const cached = uploadedCache.get(pure);
  if (cached) {
    return `/${cached}`;
  }
  const targetPath = generateImageFilename(filename, moduleDir);
  const { base64 } = extractBase64FromDataUrl(dataUrl);
  files.push({ path: targetPath, content: base64, isBase64: true });
  uploadedCache.set(pure, targetPath);
  return `/${targetPath}`;
}

export function useSiteWideSync() {
  const { getGithubApiConfig, markSyncing, markSynced, markError } = useSyncService();
  const { products, updateProductsWithGithubPaths } = useProducts();
  const { advantages } = useAdvantages();
  const { testimonials, saveTestimonials } = useTestimonials();
  const { features, sectionImage, saveFeatures, setFeatureSectionImage } = useFeatures();
  const { slides, saveSlides } = useHeroSlides();
  const { content: aboutContent, saveContent } = useAboutContent();
  const { articles, saveArticles } = useNews();
  const { categories, saveCategories } = useCategories();
  const { settings: footerSettings, updateSettings: updateFooterSettings } = useFooterSettings();
  const { settings: seoSettings, saveSettings: saveSeoSettings } = useSeoSettings();
  const { data: privacyData } = usePrivacyPolicy();

  const syncAll = useCallback(
    async (options?: SyncAllOptions) => {
      const config = getGithubApiConfig();
      if (!config) {
        options?.onComplete?.({
          successCount: 0,
          errorCount: 1,
          errors: [
            {
              module: 'all',
              label: 'All',
              message:
                'GitHub sync not configured. Go to GitHub Sync settings to set up your repository.',
            },
          ],
        });
        return {
          successCount: 0,
          errorCount: 1,
          errors: [
            {
              module: 'all',
              label: 'All',
              message:
                'GitHub sync not configured. Go to GitHub Sync settings to set up your repository.',
            },
          ],
        };
      }

      // 全局图片去重缓存
      const uploadedCache = new Map<string, string>();
      // 收集到的所有待提交文件
      const allFiles: PendingFile[] = [];
      // 各模块处理后的数据（用于提交成功后的 Storage 优化）
      const moduleResults = new Map<string, unknown>();

      const modules: SyncModuleDefinition[] = [
        {
          key: 'products',
          label: 'Products',
          collectFn: async () => {
            const { data: dataWithImages, files } = collectImagesInData(
              products,
              'products',
              ['image' as any, 'gallery' as any],
              uploadedCache
            );
            const jsonPath = 'data/products.json';
            const jsonContent = JSON.stringify(dataWithImages, null, 2);
            allFiles.push({ path: jsonPath, content: jsonContent, isBase64: false });
            allFiles.push(...files);
            return { data: dataWithImages, files };
          },
          onSuccess: async () => {
            const dataWithImages = moduleResults.get('products') as typeof products;
            if (dataWithImages) {
              try {
                await updateProductsWithGithubPaths(dataWithImages);
              } catch (e) {
                logger.warn('[Storage-optimize] Failed to save products after sync:', String(e));
              }
            }
          },
        },
        {
          key: 'advantages',
          label: 'Advantages',
          collectFn: async () => {
            const jsonPath = 'data/advantages.json';
            const jsonContent = JSON.stringify(advantages, null, 2);
            allFiles.push({ path: jsonPath, content: jsonContent, isBase64: false });
            return { data: advantages, files: [] };
          },
        },
        {
          key: 'testimonials',
          label: 'Testimonials',
          collectFn: async () => {
            const { data: dataWithImages, files } = collectImagesInData(
              testimonials,
              'testimonials',
              ['avatar' as any],
              uploadedCache
            );
            const jsonPath = 'data/testimonials.json';
            const jsonContent = JSON.stringify(dataWithImages, null, 2);
            allFiles.push({ path: jsonPath, content: jsonContent, isBase64: false });
            allFiles.push(...files);
            return { data: dataWithImages, files };
          },
          onSuccess: () => {
            const dataWithImages = moduleResults.get('testimonials') as typeof testimonials;
            if (dataWithImages) {
              try {
                saveTestimonials(dataWithImages);
              } catch (e) {
                logger.warn('[Storage-optimize] Failed to save testimonials:', String(e));
              }
            }
          },
        },
        {
          key: 'features',
          label: 'Features',
          collectFn: async () => {
            const files: PendingFile[] = [];
            const { data: featuresWithImages, files: iconFiles } = collectImagesInData(
              features,
              'features',
              ['icon' as any],
              uploadedCache
            );
            files.push(...iconFiles);
            const payload: Record<string, unknown> = { features: featuresWithImages };
            let finalSectionImage = sectionImage;
            if (sectionImage && typeof sectionImage === 'string' && isLocalBase64Image(sectionImage)) {
              finalSectionImage = collectSingleImage(
                sectionImage,
                'section-image.jpg',
                'features',
                files,
                uploadedCache
              );
              payload.sectionImage = finalSectionImage;
            } else if (sectionImage) {
              payload.sectionImage = sectionImage;
            }
            const jsonPath = 'data/features.json';
            const jsonContent = JSON.stringify(payload, null, 2);
            allFiles.push({ path: jsonPath, content: jsonContent, isBase64: false });
            allFiles.push(...files);
            moduleResults.set('features_sectionImage', finalSectionImage);
            return { data: payload, files };
          },
          onSuccess: () => {
            const payload = moduleResults.get('features') as Record<string, unknown>;
            const featuresData = payload?.features as typeof features;
            const finalSectionImage = moduleResults.get('features_sectionImage') as string;
            if (featuresData) {
              try {
                saveFeatures(featuresData);
              } catch (e) {
                logger.warn('[Storage-optimize] Failed to save features:', String(e));
              }
            }
            if (finalSectionImage && finalSectionImage !== sectionImage) {
              try {
                setFeatureSectionImage(finalSectionImage);
              } catch (e) {
                logger.warn('[Storage-optimize] Failed to save features section image:', String(e));
              }
            }
          },
        },
        {
          key: 'heroSlides',
          label: 'Hero Slides',
          collectFn: async () => {
            const { data: dataWithImages, files } = collectImagesInData(
              slides,
              'hero-slides',
              ['image' as any],
              uploadedCache
            );
            const jsonPath = 'data/hero-slides.json';
            const jsonContent = JSON.stringify(dataWithImages, null, 2);
            allFiles.push({ path: jsonPath, content: jsonContent, isBase64: false });
            allFiles.push(...files);
            return { data: dataWithImages, files };
          },
          onSuccess: () => {
            const dataWithImages = moduleResults.get('heroSlides') as typeof slides;
            if (dataWithImages) {
              try {
                saveSlides(dataWithImages);
              } catch (e) {
                logger.warn('[Storage-optimize] Failed to save hero slides:', String(e));
              }
            }
          },
        },
        {
          key: 'about',
          label: 'About Page',
          collectFn: async () => {
            const files: PendingFile[] = [];
            const aboutData = deepClone(aboutContent) as unknown as Record<string, unknown>;
            if (aboutData.heroImage && isLocalBase64Image(aboutData.heroImage as string)) {
              aboutData.heroImage = collectSingleImage(
                aboutData.heroImage as string,
                'about-hero.jpg',
                'about',
                files,
                uploadedCache
              );
            }
            if (Array.isArray(aboutData.gallery)) {
              for (const img of aboutData.gallery as Record<string, unknown>[]) {
                if (img.image && isLocalBase64Image(img.image as string)) {
                  img.image = collectSingleImage(
                    img.image as string,
                    'gallery.jpg',
                    'about/gallery',
                    files,
                    uploadedCache
                  );
                }
              }
            }
            if (Array.isArray(aboutData.certifications)) {
              for (const cert of aboutData.certifications as Record<string, unknown>[]) {
                if (cert.image && isLocalBase64Image(cert.image as string)) {
                  cert.image = collectSingleImage(
                    cert.image as string,
                    'cert.jpg',
                    'about/certifications',
                    files,
                    uploadedCache
                  );
                }
              }
            }
            const jsonPath = 'data/about.json';
            const jsonContent = JSON.stringify(aboutData, null, 2);
            allFiles.push({ path: jsonPath, content: jsonContent, isBase64: false });
            allFiles.push(...files);
            return { data: aboutData, files };
          },
          onSuccess: () => {
            const aboutData = moduleResults.get('about') as typeof aboutContent;
            if (aboutData) {
              try {
                saveContent(aboutData);
              } catch (e) {
                logger.warn('[Storage-optimize] Failed to save about content:', String(e));
              }
            }
          },
        },
        {
          key: 'news',
          label: 'News / Articles',
          collectFn: async () => {
            const { data: dataWithImages, files } = collectImagesInData(
              articles,
              'news',
              ['coverImage' as any],
              uploadedCache
            );
            const jsonPath = 'data/news.json';
            const jsonContent = JSON.stringify(dataWithImages, null, 2);
            allFiles.push({ path: jsonPath, content: jsonContent, isBase64: false });
            allFiles.push(...files);
            return { data: dataWithImages, files };
          },
          onSuccess: () => {
            const dataWithImages = moduleResults.get('news') as typeof articles;
            if (dataWithImages) {
              try {
                saveArticles(dataWithImages);
              } catch (e) {
                logger.warn('[Storage-optimize] Failed to save news:', String(e));
              }
            }
          },
        },
        {
          key: 'categories',
          label: 'Product Categories',
          collectFn: async () => {
            const { data: dataWithImages, files } = collectImagesInData(
              categories,
              'categories',
              ['iconImage' as any],
              uploadedCache
            );
            const jsonPath = 'data/categories.json';
            const jsonContent = JSON.stringify(dataWithImages, null, 2);
            allFiles.push({ path: jsonPath, content: jsonContent, isBase64: false });
            allFiles.push(...files);
            return { data: dataWithImages, files };
          },
          onSuccess: () => {
            const dataWithImages = moduleResults.get('categories') as typeof categories;
            if (dataWithImages) {
              try {
                saveCategories(dataWithImages);
              } catch (e) {
                logger.warn('[Storage-optimize] Failed to save categories:', String(e));
              }
            }
          },
        },
        {
          key: 'footer',
          label: 'Footer / Header Settings',
          collectFn: async () => {
            const files: PendingFile[] = [];
            const data = deepClone(footerSettings) as unknown as Record<string, unknown>;
            if (data.footerLogo && isLocalBase64Image(data.footerLogo as string)) {
              data.footerLogo = collectSingleImage(
                data.footerLogo as string,
                'footer-logo.png',
                'footer',
                files,
                uploadedCache
              );
            }
            if (data.headerLogo && isLocalBase64Image(data.headerLogo as string)) {
              data.headerLogo = collectSingleImage(
                data.headerLogo as string,
                'header-logo.png',
                'footer',
                files,
                uploadedCache
              );
            }
            if (data.wechatQrImage && isLocalBase64Image(data.wechatQrImage as string)) {
              data.wechatQrImage = collectSingleImage(
                data.wechatQrImage as string,
                'wechat-qr.png',
                'footer',
                files,
                uploadedCache
              );
            }
            const jsonPath = 'data/footer.json';
            const jsonContent = JSON.stringify(data, null, 2);
            allFiles.push({ path: jsonPath, content: jsonContent, isBase64: false });
            allFiles.push(...files);
            return { data, files };
          },
          onSuccess: () => {
            const data = moduleResults.get('footer') as Record<string, unknown>;
            if (data) {
              try {
                updateFooterSettings(data);
              } catch (e) {
                logger.warn('[Storage-optimize] Failed to save footer settings:', String(e));
              }
            }
          },
        },
        {
          key: 'seo',
          label: 'SEO Settings',
          collectFn: async () => {
            const files: PendingFile[] = [];
            const seoData = deepClone(seoSettings) as unknown as Record<string, unknown>;
            const globalSettings = seoData.global as Record<string, unknown> | undefined;
            if (
              globalSettings &&
              globalSettings.ogImage &&
              typeof globalSettings.ogImage === 'string' &&
              isLocalBase64Image(globalSettings.ogImage)
            ) {
              globalSettings.ogImage = collectSingleImage(
                globalSettings.ogImage,
                'og-image.jpg',
                'seo',
                files,
                uploadedCache
              );
            }
            const jsonPath = 'data/seo.json';
            const jsonContent = JSON.stringify(seoData, null, 2);
            allFiles.push({ path: jsonPath, content: jsonContent, isBase64: false });
            allFiles.push(...files);
            return { data: seoData, files };
          },
          onSuccess: () => {
            const seoData = moduleResults.get('seo') as typeof seoSettings;
            if (seoData) {
              try {
                saveSeoSettings(seoData as any);
              } catch (e) {
                logger.warn('[Storage-optimize] Failed to save SEO settings:', String(e));
              }
            }
          },
        },
        {
          key: 'privacy',
          label: 'Privacy Policy',
          collectFn: async () => {
            const jsonPath = 'data/privacy.json';
            const jsonContent = JSON.stringify(privacyData, null, 2);
            allFiles.push({ path: jsonPath, content: jsonContent, isBase64: false });
            return { data: privacyData, files: [] };
          },
        },
        {
          key: 'workflows',
          label: 'GitHub Workflows',
          collectFn: async () => {
            // 把 GitHub Actions workflow 文件推送到仓库
            // 这是询盘邮件通知的基础设施，只有放在 .github/workflows/ 下才会生效
            allFiles.push({
              path: INQUIRY_NOTIFICATION_WORKFLOW_PATH,
              content: INQUIRY_NOTIFICATION_WORKFLOW_CONTENT,
              isBase64: false,
            });
            logger.info(
              `[SiteSync] Workflow file queued: ${INQUIRY_NOTIFICATION_WORKFLOW_PATH} ` +
              `(${INQUIRY_NOTIFICATION_WORKFLOW_CONTENT.length} chars)`
            );
            return { data: { workflows: ['inquiry-notification'] }, files: [] };
          },
        },
      ];

      const total = modules.length;
      let successCount = 0;
      let errorCount = 0;
      const errors: { module: string; label: string; message: string }[] = [];

      // ========== 阶段 1：收集所有文件 ==========
      options?.onProgress?.({
        currentIndex: 0,
        total,
        currentLabel: 'Preparing files...',
        successCount: 0,
        errorCount: 0,
        errors: [],
        isSyncing: true,
        phase: 'collecting',
      });

      for (let i = 0; i < modules.length; i++) {
        const mod = modules[i];
        options?.onProgress?.({
          currentIndex: i,
          total,
          currentLabel: mod.label,
          successCount,
          errorCount,
          errors,
          isSyncing: true,
          phase: 'collecting',
        });

        markSyncing(mod.key);

        try {
          const { data } = await mod.collectFn();
          moduleResults.set(mod.key, data);
          markSynced(mod.key);
          successCount += 1;
          options?.onModuleDone?.(mod.label, true, '');
        } catch (err) {
          markError(mod.key);
          errorCount += 1;
          const msg = err instanceof Error ? err.message : String(err) || 'Unknown error';
          errors.push({ module: mod.key, label: mod.label, message: msg });
          options?.onModuleDone?.(mod.label, false, msg);
          logger.error(`[SiteSync] collect failed: ${mod.label}, error: ${msg}`);
        }
      }

      // ========== 阶段 2：批量提交 ==========
      if (errorCount > 0 && allFiles.length === 0) {
        // 完全没有可提交的文件，直接结束
        options?.onProgress?.({
          currentIndex: total,
          total,
          currentLabel: 'All done (with errors)',
          successCount,
          errorCount,
          errors,
          isSyncing: false,
          phase: 'done',
        });
        options?.onComplete?.({ successCount, errorCount, errors });
        return { successCount, errorCount, errors };
      }

      options?.onProgress?.({
        currentIndex: total,
        total,
        currentLabel: `Uploading ${allFiles.length} files (batch commit)...`,
        successCount,
        errorCount,
        errors,
        isSyncing: true,
        phase: 'committing',
      });

      logger.info(`[SiteSync] batch commit: ${allFiles.length} files total`);

      try {
        const moduleLabels = modules
          .filter((m) => !errors.some((e) => e.module === m.key))
          .map((m) => m.label.replace(/\s+/g, '-').toLowerCase())
          .join(', ');
        const commitMsg = `Sync site content: ${moduleLabels || 'site data'}`;

        const result = await createOrUpdateFilesBatch(
          config as GithubConfig,
          allFiles,
          commitMsg
        );

        logger.info(
          `[SiteSync] batch commit success: ${result.fileCount} files, commit=${result.commitSha.slice(
            0,
            7
          )}`
        );
      } catch (batchErr) {
        // 批量提交失败 — 所有模块标记为 error
        const batchMsg =
          batchErr instanceof Error ? batchErr.message : String(batchErr) || 'Batch commit failed';
        logger.error(`[SiteSync] batch commit failed: ${batchMsg}`);

        // 标记所有成功收集的模块为 error 状态
        for (const mod of modules) {
          if (!errors.some((e) => e.module === mod.key)) {
            markError(mod.key);
            errors.push({ module: mod.key, label: mod.label, message: batchMsg });
          }
        }
        errorCount = modules.length;
        successCount = 0;

        options?.onProgress?.({
          currentIndex: total,
          total,
          currentLabel: 'Batch commit failed',
          successCount,
          errorCount,
          errors,
          isSyncing: false,
          phase: 'done',
        });
        options?.onComplete?.({ successCount, errorCount, errors });
        return { successCount, errorCount, errors };
      }

      // ========== 阶段 3：Storage 优化（用 GitHub 路径替换本地 base64） ==========
      options?.onProgress?.({
        currentIndex: total,
        total,
        currentLabel: 'Optimizing local storage...',
        successCount,
        errorCount,
        errors,
        isSyncing: true,
        phase: 'optimizing',
      });

      for (const mod of modules) {
        if (errors.some((e) => e.module === mod.key)) continue;
        try {
          await mod.onSuccess?.();
        } catch (e) {
          logger.warn(`[Storage-optimize] ${mod.label}: ${String(e)}`);
        }
      }

      // ========== 完成 ==========
      options?.onProgress?.({
        currentIndex: total,
        total,
        currentLabel: 'All done',
        successCount,
        errorCount,
        errors,
        isSyncing: false,
        phase: 'done',
      });

      options?.onComplete?.({ successCount, errorCount, errors });

      return { successCount, errorCount, errors };
    },
    [
      getGithubApiConfig,
      markSyncing,
      markSynced,
      markError,
      products,
      updateProductsWithGithubPaths,
      advantages,
      testimonials,
      saveTestimonials,
      features,
      sectionImage,
      saveFeatures,
      setFeatureSectionImage,
      slides,
      saveSlides,
      aboutContent,
      saveContent,
      articles,
      saveArticles,
      categories,
      saveCategories,
      footerSettings,
      updateFooterSettings,
      seoSettings,
      saveSeoSettings,
      privacyData,
    ]
  );

  return { syncAll };
}

export default useSiteWideSync;
